mapper.select:
select cq.id, cq.qualification_no, cq.member_id, cq.player_id, cq.season_id, cq.team_id,
       cq.qualification_status, cq.is_current, cq.payment_confirmed, cq.payment_reference,
       cq.grant_reason, cq.granted_by, cq.granted_time, cq.valid_from, cq.valid_to,
       cq.revoked_by, cq.revoked_time, cq.revoke_reason, cq.remark, cq.create_time, cq.update_time, cq.is_delete
from basket_captain_qualification cq
left join basket_player_profile pp on pp.id = cq.player_id and pp.is_delete = 0
where cq.is_delete = 0
and cq.qualification_no like concat('%', #{qualificationNo}, '%')
and cq.member_id = #{memberId}
and cq.player_id = #{playerId}
and cq.season_id = #{seasonId}
and cq.qualification_status = #{qualificationStatus}
and cq.payment_reference like concat('%', #{paymentReference}, '%')
and pp.game_nickname like concat('%', #{nickname}, '%')
and cq.granted_time >= #{grantedTimeBegin}
and cq.granted_time <= #{grantedTimeEnd}
order by cq.granted_time desc

select count(1)
from basket_captain_qualification
where member_id = #{memberId}
  and season_id = #{seasonId}
  and qualification_status = 1
  and is_delete = 0

select count(1)
from basket_captain_qualification
where team_id = #{teamId}
  and season_id = #{seasonId}
  and qualification_status = 1
  and is_delete = 0
